"""Confirm the current coin reveal by title, artwork and unobstructed backdrop."""
import numpy as np
import cv2
from onboarding import locate
TITLE = ''

def coin_receipt(frame):
    if not isinstance(frame,np.ndarray) or frame.ndim!=3 or frame.shape[2]!=3 or not frame.size:return False
    h,w=frame.shape[:2]
    for left,right in ((.02,.20),(.80,.98)):
        edge=frame[round(h*.24):round(h*.90),round(w*left):round(w*right)].astype(np.float32)
        if not edge.size:return False
        blue=(edge[:,:,2]>edge[:,:,0]*1.4)&(edge[:,:,2]>edge[:,:,1]*1.2)&(edge[:,:,2]>145)
        if blue.mean()<.92:return False
    title=locate(frame,TITLE,(.30,.08,.72,.28),.94)
    if title is None:return False
    # Coin piles bob and rotate during the reveal. Confirm their large gold
    # artwork and black outline instead of requiring one animation frame.
    item=frame[round(h*.25):round(h*.73),round(w*.30):round(w*.68)]
    r,g,b=cv2.split(item)
    gold=(r>180)&(g>100)&(b<95)
    dark=np.all(item<65,axis=2)
    if gold.mean()<.12 or dark.mean()<.035:return False
    x,y=map(round,title)
    patch=frame[max(0,y-round(h*.045)):min(h,y+round(h*.045)),max(0,x-round(w*.13)):min(w,x+round(w*.13))]
    return bool(patch.size and np.all(patch>210,axis=2).mean()>.12)
